def is_primitive_root(a, p):
    if a % p == 0: return False
    n = p - 1
    for q in prime_factors(n):
        if pow(a, n // q, p) == 1: return False
    return True

def artin_constant(N=5000):
    product = 1.0
    count, n = 0, 2
    while count < N:
        if is_prime(n):
            product *= (1 - 1/(n*(n-1)))
            count += 1
        n += 1
    return product
